@push('scripts')<script>const oldItems=@json(old('items',[]));let rxIndex=0;const rxContainer=document.getElementById('rx-items');function addRx(values={}){if(rxContainer.children.length>=30)return;const el=document.getElementById('rx-template').content.cloneNode(true);el.querySelectorAll('[data-name]').forEach(input=>{input.name=`items[${rxIndex}][${input.dataset.name}]`;if(values[input.dataset.name])input.value=values[input.dataset.name]});el.querySelector('.remove-item').onclick=e=>{if(rxContainer.children.length>1)e.target.closest('.rx-item').remove()};rxContainer.append(el);rxIndex++}document.getElementById('add-item').onclick=()=>addRx();if(oldItems.length)oldItems.forEach(addRx);else addRx();</script>@endpush
